<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Http\Requests\LicenseActionRequest;
use App\Models\License;
use App\Services\LicenseService;
use Illuminate\Http\JsonResponse;
class LicenseController extends Controller { public function __construct(private LicenseService $service){} public function validateKey(LicenseActionRequest $request):JsonResponse{$hash=$this->service->hash($request->string('license_key'));$license=License::where('key_hash',$hash)->first();if(!$license||!$license->isValid())return response()->json(['valid'=>false,'status'=>'invalid'],422);return response()->json(['valid'=>true,'status'=>$license->status,'expires_at'=>$license->expires_at?->toIso8601String(),'device_limit'=>$license->max_devices]);} public function activate(LicenseActionRequest $request):JsonResponse{$hash=$this->service->hash($request->string('license_key'));$license=License::where('key_hash',$hash)->firstOrFail();abort_unless($license->isValid(),403);$deviceHash=hash_hmac('sha256',$request->string('device_id'),config('app.key'));$active=$license->devices()->whereNull('revoked_at')->count();abort_if($active >= $license->max_devices && !$license->devices()->where('device_hash',$deviceHash)->exists(),409,'Device limit reached');$device=$license->devices()->updateOrCreate(['device_hash'=>$deviceHash],['device_name'=>$request->string('device_name'),'platform'=>'windows','app_version'=>$request->string('app_version'),'last_ip'=>$request->ip(),'activated_at'=>now(),'last_seen_at'=>now(),'revoked_at'=>null]);return response()->json(['valid'=>true,'status'=>'active','expires_at'=>$license->expires_at?->toIso8601String(),'device_limit'=>$license->max_devices]);} public function deactivate(LicenseActionRequest $request):JsonResponse{$license=License::where('key_hash',$this->service->hash($request->string('license_key')))->firstOrFail();$deviceHash=hash_hmac('sha256',$request->string('device_id'),config('app.key'));$license->devices()->where('device_hash',$deviceHash)->update(['revoked_at'=>now()]);return response()->json(['valid'=>false,'status'=>'deactivated']);} }
